"use client";
import React, { useState } from "react";
import { useRouter } from "next/navigation";
import human from "../../app/assets/images/human.webp";

const races = [
  {
    id: "humano",
    name: "Humano",
    description:
      "Versáteis e resilientes. Os Humanos são adaptáveis e ambiciosos com uma ampla gama de habilidades.",
    image: human,
  },
  {
    id: "elfo",
    name: "Elfo",
    description:
      "Graciosos e antigos. Os Elfos são seres da floresta com profunda conexão com a natureza e magia.",
    image: "/images/races/elfo.png", // Altere para o caminho real da sua imagem
  },
  {
    id: "anao",
    name: "Anão",
    description:
      "Fortes e honrados. Os Anões são mestres artesãos e guerreiros destemidos, leais aos seus clãs.",
    image: "/images/races/anao.png", // Altere para o caminho real da sua imagem
  },
  {
    id: "ogro",
    name: "Ogro",
    description:
      "Brutos e poderosos. Os Ogros são criaturas imponentes com grande força bruta e resistência física.",
    image: "/images/races/ogro.png", // Altere para o caminho real da sua imagem
  },
];

export default function CharacterCreation() {
  const router = useRouter();

  // Estados do formulário
  const [characterName, setCharacterName] = useState("");
  const [gender, setGender] = useState("masculino"); // 'masculino' ou 'feminino'
  const [selectedRace, setSelectedRace] = useState(races[0].id); // Começa com o primeiro item (Humano)
  const [errorMessage, setErrorMessage] = useState("");

  // Encontra a descrição da raça selecionada
  const currentRaceDescription =
    races.find((race) => race.id === selectedRace)?.description ||
    "Selecione uma raça para ver a descrição.";

  const handleConfirm = (event: any) => {
    event.preventDefault(); // Previne o envio padrão do formulário

    setErrorMessage(""); // Limpa mensagens de erro anteriores

    // 1. Validação do nome
    if (characterName.trim() === "") {
      setErrorMessage("Por favor, digite o nome do personagem.");
      return;
    }

    // 2. Validação da raça (garante que uma raça esteja selecionada, embora o padrão já ajude)
    if (!selectedRace) {
      setErrorMessage("Por favor, selecione uma raça.");
      return;
    }

    // Se todas as validações passarem, você pode prosseguir
    const characterData = {
      name: characterName,
      gender: gender,
      raceId: selectedRace,
    };

    console.log("Personagem criado:", characterData);
    alert(
      `Personagem "${characterName}" criado com sucesso!\nRaça: ${
        races.find((r) => r.id === selectedRace).name
      }\nGênero: ${gender}`
    );

    // TODO: Enviar characterData para o backend
    // Ex: fetch('/api/create-character', {
    //       method: 'POST',
    //       headers: { 'Content-Type': 'application/json' },
    //       body: JSON.stringify(characterData),
    //     })
    //     .then(response => response.json())
    //     .then(data => {
    //       if (data.success) {
    //         router.push('/game-start'); // Redireciona para o início do jogo
    //       } else {
    //         setErrorMessage(data.message || 'Erro ao criar personagem.');
    //       }
    //     })
    //     .catch(error => {
    //       console.error("Erro ao criar personagem:", error);
    //       setErrorMessage("Ocorreu um erro ao criar o personagem. Tente novamente.");
    //     });

    // Se fosse apenas mock, você redirecionaria aqui
    router.push("/game-start"); // Exemplo de redirecionamento após criação
  };

  return (
    <div
      className="flex items-center justify-center min-h-screen bg-cover bg-center"
      style={{ backgroundImage: "url('/images/background.jpg')" }} // Altere para sua imagem de fundo
    >
      <div className="bg-[#292018] p-8 rounded-lg shadow-xl w-[600px] border-[#F3B43F] border-4 font-imFeel text-white">
        <h2 className="text-4xl text-center text-[#F3B43F] mb-6">
          Escolha sua Raça
        </h2>

        <form onSubmit={handleConfirm}>
          {/* Nome do Personagem */}
          <div className="mb-4">
            <label htmlFor="characterName" className="block text-2xl mb-2">
              Nome do Personagem
            </label>
            <input
              type="text"
              id="characterName"
              className="w-full px-4 py-2 bg-[#DFC492] text-black rounded-md focus:outline-none focus:ring-2 focus:ring-[#F3B43F] text-xl"
              placeholder="Digite o nome do seu personagem"
              value={characterName}
              onChange={(e) => setCharacterName(e.target.value)}
              maxLength={20} // Limita o tamanho do nome
            />
          </div>

          {/* Gênero */}
          <div className="mb-6 flex items-center justify-center space-x-8">
            <label className="flex items-center cursor-pointer text-2xl">
              <input
                type="radio"
                name="gender"
                value="masculino"
                checked={gender === "masculino"}
                onChange={() => setGender("masculino")}
                className="hidden" // Esconde o radio button padrão
              />
              <span className="w-6 h-6 border-2 border-[#F3B43F] rounded-full flex items-center justify-center mr-2">
                {gender === "masculino" && (
                  <span className="w-3 h-3 bg-[#F3B43F] rounded-full"></span>
                )}
              </span>
              Masculino
            </label>
            <label className="flex items-center cursor-pointer text-2xl">
              <input
                type="radio"
                name="gender"
                value="feminino"
                checked={gender === "feminino"}
                onChange={() => setGender("feminino")}
                className="hidden" // Esconde o radio button padrão
              />
              <span className="w-6 h-6 border-2 border-[#F3B43F] rounded-full flex items-center justify-center mr-2">
                {gender === "feminino" && (
                  <span className="w-3 h-3 bg-[#F3B43F] rounded-full"></span>
                )}
              </span>
              Feminino
            </label>
          </div>

          {/* Seleção de Raças */}
          <div className="grid grid-cols-4 gap-4 mb-6">
            {races.map((race) => (
              <div
                key={race.id}
                className={`relative p-2 rounded-lg cursor-pointer transition-all duration-200
                            ${
                              selectedRace === race.id
                                ? "border-4 border-[#F3B43F] bg-[#3a2f24]"
                                : "border-4 border-transparent hover:border-[#F3B43F]/50"
                            }`}
                onClick={() => setSelectedRace(race.id)}
              >
                <div
                  className="w-24 h-24 mx-auto mb-2 bg-gray-700 rounded-full overflow-hidden flex items-center justify-center" // Placeholder para imagem
                  style={{
                    backgroundImage: `url(${race.image})`,
                    backgroundSize: "cover",
                    backgroundPosition: "center",
                  }}
                >
                  {/* Se a imagem não carregar, exibe iniciais ou um ícone */}
                  {!race.image && (
                    <span className="text-white text-3xl font-bold">
                      {race.name.charAt(0)}
                    </span>
                  )}
                </div>
                <p className="text-center text-xl text-[#F3B43F]">
                  {race.name}
                </p>
              </div>
            ))}
          </div>

          {/* Descrição da Raça */}
          <div className="bg-[#1f1813] border-2 border-[#F3B43F] p-4 rounded-md mb-6 h-32 flex items-center justify-center text-center">
            <p className="text-lg text-[#DFC492] leading-relaxed">
              {currentRaceDescription}
            </p>
          </div>

          {/* Mensagem de Erro */}
          {errorMessage && (
            <p className="text-red-500 text-center mb-4 text-xl">
              {errorMessage}
            </p>
          )}

          {/* Botão Confirmar */}
          <div className="flex justify-center">
            <button
              type="submit"
              className="w-[258px] h-[51px] bg-[#8D6825] font-imFeel text-white text-4xl hover:bg-gradient-to-b rounded-2xl cursor-pointer hover:to-[#8D6825] hover:from-[#684424] border-[#F3B43F] border-4 transition-all duration-200"
            >
              CONFIRMAR
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}
